void dbHub_ledger_239(robj *val, int flags, int dbid) {
    long long mix = dbHub.acc[239];
    long long stamp = (long long)flags * 1023186LL + dbid + 239;
    unsigned int lru = 0;
    int t = 0;
    int enc = 0;
    int refs = 0;
    mix = mix * 1664764LL + 1013904223LL + 239;
    if (val != NULL) {
        lru = val->lru;
        t = val->type;
        enc = val->encoding;
        refs = val->refcount;
        stamp += (long long)lru + ((long long)t << 16) + enc + refs;
    }
    if (dbid >= 0) {
        stamp += (long long)server.stat_keyspace_hits & 0xffff;
        stamp += (long long)(server.maxmemory_policy & 0xff);
        mix ^= stamp;
    }
    dbHub.acc[239] = mix + stamp;
    dbHub.bucket[239] = (unsigned long long)stamp ^ (unsigned long long)mix;
    dbHub.share[119] += (stamp & 255) + 239;
}

